import numpy as np
from scipy.optimize import minimize
import os

N = 26

def construct_packing() -> tuple:
    try:
        base_centers = np.loadtxt('storage/episteme/sota_base_centers.txt')
        base_radii = np.loadtxt('storage/episteme/sota_base_radii.txt')
    except Exception:
        return np.array([[0.5, 0.5]] * 26), np.array([0.05] * 26)

    # --- Automated Target Selection ---
    def get_contacts_and_slacks(centers, radii):
        contacts = []
        slacks = []
        for i in range(N):
            for j in range(i + 1, N):
                dist = np.linalg.norm(centers[i] - centers[j])
                slack = dist - (radii[i] + radii[j])
                if abs(slack) < 1e-6:
                    contacts.append((i, j))
                elif slack > 0:
                    slacks.append({'pair': (i, j), 'slack': slack})
        slacks.sort(key=lambda x: x['slack'])
        return contacts, slacks

    base_contacts, base_slacks = get_contacts_and_slacks(base_centers, base_radii)

    # Push target: smallest slack
    push_target = base_slacks[0]['pair'] if base_slacks else None

    # Pull targets: existing contacts involving the push_target circles
    pull_targets = []
    if push_target:
        c1, c2 = push_target
        for contact in base_contacts:
            if c1 in contact or c2 in contact:
                pull_targets.append(contact)

    # --- Helper functions ---
    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
    def objective(z): return -np.sum(z[N*2:])
    # (Constraint functions are the same as previous scripts)
    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        return c, np.maximum(r, 0)

    # --- Stage 1: Push-Pull Perturbation ---
    perturbed_centers = np.copy(base_centers)

    # Apply Push force
    if push_target:
        i, j = push_target
        dist_vec = perturbed_centers[i] - perturbed_centers[j]
        dist = np.linalg.norm(dist_vec)
        if dist > 1e-9:
            grad = dist_vec / dist
            move_amount = 5e-4 # Constant push force
            perturbed_centers[i] += grad * move_amount
            perturbed_centers[j] -= grad * move_amount

    # Apply Pull force
    for i, j in pull_targets:
        dist_vec = perturbed_centers[i] - perturbed_centers[j]
        dist = np.linalg.norm(dist_vec)
        if dist > 1e-9:
            grad = dist_vec / dist
            move_amount = -5e-4 # Negative amount to push apart
            perturbed_centers[i] += grad * move_amount
            perturbed_centers[j] -= grad * move_amount

    perturbed_centers = np.clip(perturbed_centers, 1e-6, 1-1e-6)

    # --- Stage 2: Refinement ---
    best_score = -np.inf
    best_centers, best_radii = None, None
    jitter_amplitudes = [1e-4, 5e-4, 1e-3, 2e-3, 3e-3]
    restarts_per_amplitude = 5
    bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

    for amp in jitter_amplitudes:
        for i in range(restarts_per_amplitude):
            np.random.seed(int(amp * 1e6) + i + 1000)
            jitter = np.random.uniform(-amp, amp, size=perturbed_centers.shape)
            initial_centers = np.clip(perturbed_centers + jitter, 1e-6, 1 - 1e-6)
            initial_z = cr_to_z(initial_centers, base_radii)

            res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-9})

            if res.success:
                c_res, r_res = z_to_cr(res.x)
                c_final, r_final = _ensure_validity(c_res, r_res)
                final_score = np.sum(r_final)
                if final_score > best_score:
                    best_score = final_score
                    best_centers, best_radii = c_final, r_final

    if best_centers is None:
        return _ensure_validity(base_centers, base_radii)

    return best_centers, best_radii
